fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}

const TRANSFORM:&[FloatColumn]=&[FloatColumn::Binary32(1),FloatColumn::Binary32(2),FloatColumn::Binary32(3),FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6),FloatColumn::Binary32(7),FloatColumn::Binary32(8),FloatColumn::Binary32(9)];
const OPACITY:&[FloatColumn]=&[FloatColumn::Binary32(5)];
fn plus(value:&mut usize,additional:usize)->Result<(),ValueError>{*value=value.checked_add(additional).ok_or_else(||invalid("Lowpoly admission overflow"))?;Ok(())}
fn rows(snapshot:&LowpolySnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<usize,ValueError>{
 let mut rows=1usize;let mut bytes=snapshot.schema.len();control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,snapshot.objects.len())?;
 for(index,object)in snapshot.objects.iter().enumerate(){plus(&mut rows,2)?;for value in[&object.id,&object.name,&object.mesh_content]{plus(&mut bytes,value.len())?;}
 if let Some(child)=&object.mesh{plus(&mut rows,1)?;for value in[&child.child_id,&child.target.artifact_id,&child.target.dialect.artifact_kind,&child.target.dialect.standard,&child.target.dialect.subset]{plus(&mut bytes,value.len())?;}}
