 control.check_rows(rows)?;control.check_value_bytes(bytes.checked_add(rows.checked_mul(192).ok_or_else(||invalid("Lowpoly lookup admission overflow"))?).ok_or_else(||invalid("Lowpoly value admission overflow"))?)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,index+1,snapshot.objects.len())?;}
 }control.check_rows(rows)?;control.check_value_bytes(bytes.checked_add(rows.checked_mul(192).ok_or_else(||invalid("Lowpoly lookup admission overflow"))?).ok_or_else(||invalid("Lowpoly value admission overflow"))?)?;Ok(rows)
}
fn native_rows(record:&semio_framework_dsl_record::RecordValue,control:&mut semio_framework_value::NativeDecodeControl<'_>,maximum:usize)->Result<(),ValueError>{
 fn list(record:&semio_framework_dsl_record::RecordValue,id:u16)->Result<&[semio_framework_dsl_record::FieldValue],ValueError>{match record.get(id){Some(semio_framework_dsl_record::FieldValue::List(values))=>Ok(values),_=>Err(invalid("Lowpoly native ordered occurrence field differs"))}}
 fn owned(value:&semio_framework_dsl_record::FieldValue)->Result<&semio_framework_dsl_record::RecordValue,ValueError>{match value{semio_framework_dsl_record::FieldValue::Record(value)=>Ok(value),_=>Err(invalid("Lowpoly native typed object differs"))}}
 let objects=list(record,1)?;let mut count=1usize;control.begin_stage(objects.len())?;
 for value in objects{control.step()?;let object=owned(value)?;plus(&mut count,2)?;match object.get(4){None|Some(semio_framework_dsl_record::FieldValue::Absent)=>{},Some(semio_framework_dsl_record::FieldValue::Record(_))=>plus(&mut count,1)?,_=>return Err(invalid("Lowpoly native optional mesh field differs"))}
 let layers=list(object,5)?;control.scoped_stage(|control|->Result<(),ValueError>{control.begin_stage(layers.len())?;for value in layers{control.step()?;let layer=owned(value)?;let bytes=match layer.get(4){Some(semio_framework_dsl_record::FieldValue::Bytes64(bytes))=>bytes.len(),_=>return Err(invalid("Lowpoly native intrinsic pixel bytes differ"))};plus(&mut count,1)?;plus(&mut count,bytes)?;if count>maximum{return Err(invalid("Lowpoly native semantic row limit"))}}Ok(())})?;if count>maximum{return Err(invalid("Lowpoly native semantic row limit"))}
 }if count>maximum{return Err(invalid("Lowpoly native semantic row limit"))}control.checkpoint()
}
fn keyed<'a>(rows:&'a[SqliteRow],width:usize,control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<BTreeMap<i64,&'a SqliteRow>,ValueError>{control.begin_stage(rows.len())?;let mut result=BTreeMap::new();for row in rows{control.step()?;if row.values.len()!=width||row.integer(0)?!=row.rowid||result.insert(row.rowid,row).is_some(){return Err(invalid("Lowpoly identity or row width differs"))}}Ok(result)}
fn boolean(row:&SqliteRow,index:usize)->Result<bool,ValueError>{match row.integer(index)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("Lowpoly boolean exceeds its domain"))}}
fn grouped<'a>(rows:&'a[SqliteRow],column:usize,parents:&BTreeMap<i64,&SqliteRow>,control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,ValueError>{control.begin_stage(rows.len())?;let mut result=BTreeMap::new();for row in rows{control.step()?;let owner=row.integer(column)?;if !parents.contains_key(&owner){return Err(invalid("Lowpoly occurrence has an unknown owner"))}result.entry(owner).or_insert_with(Vec::new).push(row);}Ok(result)}
fn ordered<'a>(rows:Vec<&'a SqliteRow>,column:usize,control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,ValueError>{control.begin_stage(rows.len())?;let mut result=control.allocate_vec::<Option<&SqliteRow>>(rows.len())?;result.resize(rows.len(),None);for row in rows{control.step()?;let ordinal=usize::try_from(row.integer(column)?).map_err(|_|invalid("Lowpoly ordinal exceeds native width"))?;if ordinal>=result.len()||result[ordinal].replace(row).is_some(){return Err(invalid("Lowpoly ordinals are not contiguous"))}}let mut values=control.allocate_vec(result.len())?;for row in result{values.push(row.ok_or_else(||invalid("Lowpoly missing ordinal"))?);}Ok(values)}
impl ArtifactSqliteSnapshot for LowpolySnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{
  control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,self.objects.len())?;let mut count=1usize;control.check_rows(count)?;for(index,object)in self.objects.iter().enumerate(){plus(&mut count,2)?;if object.mesh.is_some(){plus(&mut count,1)?;}control.check_rows(count)?;control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,object.paint_layers.len())?;for(index,layer)in object.paint_layers.iter().enumerate(){plus(&mut count,1)?;plus(&mut count,layer.pixels.len())?;control.check_rows(count)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,object.paint_layers.len())?;}}control.checkpoint(SqliteSnapshotPhase::EncodeNative,object.paint_layers.len(),object.paint_layers.len())?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,self.objects.len())?;}}control.checkpoint(SqliteSnapshotPhase::EncodeNative,self.objects.len(),self.objects.len())?;
  store::encode_sqlite_snapshot_record_native(encoding,"lowpoly.lowpoly",Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)
 }
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{let maximum=control.limits().max_rows;store::decode_sqlite_snapshot_record_native(payload,"lowpoly.lowpoly",Self::__dsl_spec_producer(),|record,native|{native.scoped_stage(|native|native_rows(record,native,maximum))?;Self::__dsl_from_record_controlled(record,native)},control)}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut bound=NativeEncodingBound::new(control)?;bound.add(4096)?;bound.repeated(self.schema.len(),12)?;for object in&self.objects{bound.add(4096)?;for value in[&object.id,&object.name,&object.mesh_content]{bound.repeated(value.len(),12)?;}if let Some(child)=&object.mesh{bound.add(2048)?;for value in[&child.child_id,&child.target.artifact_id,&child.target.dialect.artifact_kind,&child.target.dialect.standard,&child.target.dialect.subset]{bound.repeated(value.len(),12)?;}}for layer in&object.paint_layers{bound.add(2048)?;bound.repeated(layer.name.len(),12)?;bound.repeated(layer.blend_mode.len(),12)?;bound.repeated(layer.pixels.len(),8)?;}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{
 let total=rows(self,control)?;let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key("lowpoly_document",1,&[Cell::Text(&self.schema)])?;let mut layer_id=0i64;
 for(index,object)in self.objects.iter().enumerate(){let ordinal=i64::try_from(index).map_err(|_|invalid("Lowpoly occurrence ordinal exceeds SQLite integer"))?;let id=ordinal.checked_add(1).ok_or_else(||invalid("Lowpoly identity overflow"))?;p.insert_key("lowpoly_object",id,&[Cell::Integer(1),Cell::Integer(ordinal),Cell::Text(&object.id),Cell::Text(&object.name),Cell::Integer(i64::from(object.smooth_shading)),Cell::Text(&object.mesh_content)])?;
 let t=&object.transform;insert_key_ieee754(&mut p,"lowpoly_transform",id,&[Cell::Float32(t.position[0]),Cell::Float32(t.position[1]),Cell::Float32(t.position[2]),Cell::Float32(t.rotation[0]),Cell::Float32(t.rotation[1]),Cell::Float32(t.rotation[2]),Cell::Float32(t.scale[0]),Cell::Float32(t.scale[1]),Cell::Float32(t.scale[2])],TRANSFORM)?;
 if let Some(child)=&object.mesh{p.insert_key("lowpoly_mesh_child",id,&[Cell::Text(&child.child_id),Cell::Text(&child.target.artifact_id),Cell::Text(&child.target.dialect.artifact_kind),Cell::Text(&child.target.dialect.standard),Cell::Text(&child.target.dialect.subset)])?;}
 for(index,layer)in object.paint_layers.iter().enumerate(){layer_id=layer_id.checked_add(1).ok_or_else(||invalid("Lowpoly layer identity overflow"))?;insert_ieee754(&mut p,"lowpoly_paint_layer",&[Cell::Integer(id),Cell::Integer(i64::try_from(index).map_err(|_|invalid("Lowpoly layer ordinal exceeds SQLite integer"))?),Cell::Text(&layer.name),Cell::Integer(i64::from(layer.visible)),Cell::Float32(layer.opacity),Cell::Text(&layer.blend_mode)],OPACITY)?;
 for(index,byte)in layer.pixels.iter().enumerate(){p.insert("lowpoly_paint_octet",&[Cell::Integer(layer_id),Cell::Integer(i64::try_from(index).map_err(|_|invalid("Lowpoly pixel ordinal exceeds SQLite integer"))?),Cell::Integer(i64::from(*byte))])?;if(index+1)%256==0{p.checkpoint_total(total)?;}}}
 }p.checkpoint_total(total)?;p.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{
 control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|invalid(e.to_string()))?;let total=database.tables.iter().try_fold(0usize,|n,t|n.checked_add(t.rows.len()).ok_or_else(||invalid("Lowpoly row count overflow")))?;control.check_value_bytes(total.checked_mul(192).ok_or_else(||invalid("Lowpoly lookup admission overflow"))?)?;
 let maximum=control.limits().max_value_bytes;let mut progress=|state:semio_framework_value::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,state.completed,state.total).is_ok();let mut native=semio_framework_value::NativeDecodeControl::new(maximum,&mut progress);native.charge(total.checked_mul(192).ok_or_else(||invalid("Lowpoly lookup admission overflow"))?)?;native.begin_stage(total)?;
