 let documents=keyed(&database.table("lowpoly_document")?.rows,2,&mut native)?;let objects=keyed(&database.table("lowpoly_object")?.rows,7,&mut native)?;let mut transforms=keyed(&database.table("lowpoly_transform")?.rows,28,&mut native)?;let mut children=keyed(&database.table("lowpoly_mesh_child")?.rows,6,&mut native)?;let layers=keyed(&database.table("lowpoly_paint_layer")?.rows,9,&mut native)?;let octets=database.table("lowpoly_paint_octet")?;keyed(&octets.rows,4,&mut native)?;
 if documents.len()!=1||transforms.len()!=objects.len(){return Err(invalid("Lowpoly document or transform cardinality differs"))}let document=*documents.values().next().ok_or_else(||invalid("Lowpoly document missing"))?;for object in objects.values(){if object.integer(1)?!=document.rowid{return Err(invalid("Lowpoly object document differs"))}}
 let mut layer_groups=grouped(&database.table("lowpoly_paint_layer")?.rows,1,&objects,&mut native)?;let mut octet_groups=grouped(&octets.rows,1,&layers,&mut native)?;let mut object_rows=native.allocate_vec(objects.len())?;native.begin_stage(objects.len())?;for row in objects.values(){native.step()?;object_rows.push(*row);}let ordered_objects=ordered(object_rows,2,&mut native)?;let mut result=LowpolySnapshot{schema:native.copy_text(document.text(1)?)?,objects:native.allocate_vec(ordered_objects.len())?};
 for row in ordered_objects{native.checkpoint()?;let transform=FloatRow::new(transforms.remove(&row.rowid).ok_or_else(||invalid("Lowpoly transform owner missing"))?,TRANSFORM)?;let transform=LowpolyTransform{position:[transform.binary32(1)?,transform.binary32(2)?,transform.binary32(3)?],rotation:[transform.binary32(4)?,transform.binary32(5)?,transform.binary32(6)?],scale:[transform.binary32(7)?,transform.binary32(8)?,transform.binary32(9)?]};
 let mesh=if let Some(child)=children.remove(&row.rowid){Some(store::ArtifactChild::new(native.copy_text(child.text(1)?)?,store::io_schema::ArtifactRef{artifact_id:native.copy_text(child.text(2)?)?,dialect:store::io_schema::ArtifactDialect{artifact_kind:native.copy_text(child.text(3)?)?,standard:native.copy_text(child.text(4)?)?,subset:native.copy_text(child.text(5)?)?}}))}else{None};
 let rows=ordered(layer_groups.remove(&row.rowid).unwrap_or_default(),2,&mut native)?;let mut paint_layers=native.allocate_vec(rows.len())?;
 for layer in rows{native.checkpoint()?;let rows=ordered(octet_groups.remove(&layer.rowid).unwrap_or_default(),2,&mut native)?;let mut pixels=native.allocate_vec(rows.len())?;native.begin_stage(rows.len())?;for row in rows{native.step()?;pixels.push(u8::try_from(row.integer(3)?).map_err(|_|invalid("Lowpoly paint sample exceeds octet"))?);}paint_layers.push(LowpolyPaintLayer{name:native.copy_text(layer.text(3)?)?,visible:boolean(layer,4)?,opacity:FloatRow::new(layer,OPACITY)?.binary32(5)?,blend_mode:native.copy_text(layer.text(6)?)?,pixels});}
