 }if !transforms.is_empty()||!children.is_empty()||!layer_groups.is_empty()||!octet_groups.is_empty(){return Err(invalid("Lowpoly unowned semantic entities"))}native.checkpoint()?;Ok(result)
 }
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.lowpoly.lowpoly"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("Lowpoly does not own this semantic subset")))}let candidate=Self::from_sqlite_database(database,control).map_err(store::io_schema::IoError::from_value_error)?;if candidate.to_sqlite_database(control).map_err(store::io_schema::IoError::from_value_error)?!=self.to_sqlite_database(control).map_err(store::io_schema::IoError::from_value_error)?{return Err(store::io_schema::IoError::from_value_error(invalid("Lowpoly logical snapshot state differs")))}Ok(store::io_schema::IoOutcome::clean(()))}
